import { expect, expectStatus, test } from "../../fixtures";

test.describe("LIF-03 vendor lifecycle", () => {
  test(
    "approving a decision on a vendor that was sent back returns 409 vendor_not_in_review",
    { tag: "@LIF-03" },
    async ({ apiAs }) => {
      // Arrange: a unique vendor, two documents, and a submission so the vendor is in review.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const created = await expectStatus<{ id: string }>(
        await member.post("/api/vendors", {
          data: {
            name: `LIF-03 Vendor ${suffix}`,
            category: "services",
            contact_email: `ap-${suffix}@lif03.example.test`,
          },
        }),
        201,
      );
      const vendorId = created.id;

      const w9 = await expectStatus<{ id: string }>(
        await member.post(`/api/vendors/${vendorId}/documents`, {
          multipart: {
            kind: "w9",
            file: { name: "w9.pdf", mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4 LIF-03 w9") },
          },
        }),
        201,
      );

      const contract = await expectStatus<{ id: string }>(
        await member.post(`/api/vendors/${vendorId}/documents`, {
          multipart: {
            kind: "contract",
            file: { name: "contract.pdf", mimeType: "application/pdf", buffer: Buffer.from("%PDF-1.4 LIF-03 contract") },
          },
        }),
        201,
      );

      await expectStatus(await member.post(`/api/vendors/${vendorId}/submit`), 200);

      const w9Extraction = await expectStatus<{ id: string }>(
        await reviewer.get(`/api/documents/${w9.id}/extraction`),
        200,
      );
      const contractExtraction = await expectStatus<{ id: string }>(
        await reviewer.get(`/api/documents/${contract.id}/extraction`),
        200,
      );

      // Arrange: the reviewer rejects the w9 extraction, sending the vendor back.
      await expectStatus(
        await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
          data: { decision: "reject", note: "LIF-03 w9 sent back" },
        }),
        200,
      );

      // Act: the reviewer tries to approve the contract extraction on the sent-back vendor.
      const response = await reviewer.post(`/api/extractions/${contractExtraction.id}/decision`, {
        data: { decision: "approve" },
      });

      // Assert
      const body = await expectStatus<{ error: { code: string } }>(response, 409);
      expect(body.error.code).toBe("vendor_not_in_review");
    },
  );
});
